script.code:
let entry = {{workflowparams:allData}};

if(entry.so_no_type !== -9999 && (
  !entry.so_no || entry.so_no === null || entry.so_no === ''
)) {
  entry.so_no = 'draft'
}

return { entry };

return {
  required_fields: JSON.stringify([
  { name: "plant_name", label: "Plant" },
  { name: "so_no", label: "Sales Order Number" },
  { name: "acc_integration_type", label: "Accounting Integration Type" },
  {
    name: "table_so",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    plant_name: {{node:code_node_hVnUCBf3.data.entry.plant_name}},
    so_no: {{node:code_node_hVnUCBf3.data.entry.so_no}},
    table_so: {{node:code_node_hVnUCBf3.data.entry.table_so}},
    acc_integration_type: {{node:code_node_hVnUCBf3.data.entry.acc_integration_type}}
  })
}

let entry = {{workflowparams:allData}};

if (
  entry.so_no_type !== -9999 &&
  (!entry.so_no ||
    entry.so_no === null ||
    entry.so_no === "" ||
    entry.previous_status == "Draft")
) {
  entry.so_no = 'issued'
}

if(!entry.need_cl || entry.need_cl === '' || entry.need_cl === null) {
  if(entry.acc_integration_type !== 'No Accounting') {
    entry.need_cl = 'required'
  } else {
    entry.need_cl = 'not required'
  }
}

return { entry };

return {
  required_fields: JSON.stringify([
  { name: "so_no", label: "SO Number" },
  { name: "customer_name", label: "Customer" },
  { name: "plant_name", label: "Plant" },
  { name: "so_date", label: "Sales Order Date" },
  { name: "so_payment_term", label: "Payment Term" },
  { name: "acc_integration_type", label: "Accounting Integration Type" },
  {
    name: "table_so",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    plant_name: {{node:code_node_X4j8BSXd.data.entry.plant_name}},
    so_date: {{node:code_node_X4j8BSXd.data.entry.so_date}},
    so_payment_term: {{node:code_node_X4j8BSXd.data.entry.so_payment_term}},
    so_no: {{node:code_node_X4j8BSXd.data.entry.so_no}},
    customer_name: {{node:code_node_X4j8BSXd.data.entry.customer_name}},
    table_so: {{node:code_node_X4j8BSXd.data.entry.table_so}},
    acc_integration_type: {{node:code_node_X4j8BSXd.data.entry.acc_integration_type}}
  })
}

return {
  lineItem: JSON.stringify({{node:code_node_X4j8BSXd.data.entry.table_so}}),
  itemFields: 'item_name,item_id,so_desc',
  quantityFields: 'so_quantity'
}

let table = {{node:code_node_X4j8BSXd.data.entry}};

table.table_so = table.table_so.filter(item => (item.item_name || item.so_desc || item.item_id) && item.so_quantity > 0)

return { table };

return {
  length: {{node:code_node_rPqQy5CD.data.table.table_so}}.length
}

return {
  message: 'This SO has 0 total amount. Do you wish to continue to create SI?'
}

const draftGDCount = {{node:search_node_TmnClGAM.data.total}};
const draftSICount = {{node:search_node_UmwyM0pM.data.total}};
let message = [];
let status = 'Passed';

if(draftGDCount > 0) {
  const draftGDNo = {{node:search_node_TmnClGAM.data.data.delivery_no}};
  message.push(draftGDNo);
}

if(draftSICount > 0) {
  const draftSINo = {{node:search_node_UmwyM0pM.data.data.sales_invoice_no}};
  message.push(draftSINo);
}

if(message.length > 0) {
  status = 'Failed'
}

return {
  status: status,
  message: status === 'Passed' ? '' : 'The sales order has existing GD/SI records in draft status. Proceeding will delete these record: ' + message.join(', ')
}

const message = {{node:workflow_node_1IYhCFaV.data.message}};
const isBlock = message.indexOf('Block - ') !== -1 ? 'block' : 'override';

return {
  isBlock
}

let soData = {{node:code_node_rPqQy5CD.data.table}};
let needCL = soData.need_cl;
if(needCL == 'required') {
  const clResult = {{node:workflow_node_1IYhCFaV.data.result}};
  if(clResult === 'failed') {
    const isBlock = {{node:code_node_vqKDnsnD.data.isBlock}};
    if(isBlock === 'override') {
      soData.cl_result = 'override';
    }
  }
}
//Check line item all got unit price got pass or not
//Fail is one got not pass the unit price
//Return message like whick line is fail (soData, message)
//separate max and min tasks

let message = "";

// Flatten the line items and their children into a single array
const flattenLineItems = (items) => {
    const result = [];

    for (const item of items || []) {
        result.push(item);

        if (Array.isArray(item.children)) {
            result.push(...flattenLineItems(item.children));
        }
    }

    return result;
};

const items = flattenLineItems(soData.table_so || []).map((item, index) => ({
    ...item,
    lineNo: index + 1
}));

const minFailed = items.filter((item) => {
    const unitPrice = parseFloat(item.so_item_price);
    const minPrice = parseFloat(item.min_price);

    if (
      item.min_price == null ||
      item.min_price === "" ||
      Number.isNaN(minPrice) ||
      minPrice === 0
    ) {
      return false;
    }

    return unitPrice < minPrice;
});

const maxFailed = items.filter((item) => {
    const unitPrice = parseFloat(item.so_item_price);
    const maxPrice = parseFloat(item.max_price);

    if (
      item.max_price == null ||
      item.max_price === "" ||
      Number.isNaN(maxPrice) ||
      maxPrice === 0
    ) {
      return false;
    }

    return unitPrice > maxPrice;
  });

soData.min_price_result = 
  minFailed.length > 0 ? "failed" : "passed";

soData.max_price_result = 
  maxFailed.length > 0 ? "failed" : "passed";

if (minFailed.length > 0) {
  message += minFailed
    .map(item =>
      `Line ${item.lineNo}: Unit Price ${item.so_item_price} is below Min Price ${item.min_price}`
    )
    .join("<br>");
}

if (maxFailed.length > 0) {
  if (message) {
    message += "<br>";
  }

  message += maxFailed
    .map(item =>
      `Line ${item.lineNo}: Unit Price ${item.so_item_price} exceeds Max Price ${item.max_price}`
    )
    .join("<br>");
}

return { soData, message };

// Does this edit touch anything a delivery or a picking plan is holding? A cheap
// id-keyed diff, so an edit that only changed header fields never pays for the
// cascade call. code_node_rPqQy5CD has already dropped blank and zero-quantity
// lines, so a line the user cleared arrives here as a removal.
const prevRaw = {{node:get_node_rvjWbHBF.data.data}};
const nextTable = {{node:code_node_rPqQy5CD.data.table}};
const allData = {{workflowparams:allData}};

const before = Array.isArray(prevRaw) ? prevRaw[0] || {} : prevRaw || {};
const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const sid = (v) => String(v === null || v === undefined ? "" : v);
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };

const prevLines = flat(before.table_so).filter((r) => r && r.id);
const nextLines = flat(nextTable && nextTable.table_so).filter((r) => r);
const nextById = {};
nextLines.forEach((r) => { if (r.id) nextById[sid(r.id)] = r; });

let needsCascade = 0;
prevLines.forEach((r) => {
  const after = nextById[sid(r.id)];
  if (!after) { needsCascade = 1; return; }
  if (sid(after.item_name) !== sid(r.item_name)) { needsCascade = 1; return; }
  if (Math.abs(num(after.so_quantity) - num(r.so_quantity)) > 0.0005) { needsCascade = 1; }
});

return {
  needsCascade: needsCascade,
  soId: sid(before.id || allData.id),
  prevTableSo: before.table_so || [],
  nextTableSo: (nextTable && nextTable.table_so) || [],
  // The confirm answers ride inside allData, the way need_cl and create_si already do.
  confirmPickReversal: sid(allData.confirmPickReversal),
  raiseGdQty: sid(allData.raiseGdQty)
};

// The gates return HTTP 200 with the code in the BODY, the way GDheadWorkflow's
// return-nodes do. A non-2xx end-node makes runWorkflow REJECT, and the platform then
// raises its own error toast beside the confirm -- rendering the raw <br> tags, because
// that toast takes no dangerouslyUseHTMLString. gateCode is what tells the client this
// is a gate rather than a saved order.
return {
  gate: {
    gateCode: {{node:workflow_node_CascadeA.data.code}} || "",
    message: {{node:workflow_node_CascadeA.data.message}} || ""
  }
};

const src = {{workflowparams:allData.created_source}} || '';

// Web / Mobile already compute packing + weight in the form (SOchangeItem /
// SOonChangeUOM). Internal Trading gets them from POsaveWorkflow's Build SO
// Payload. Everything else lands here with the fields empty.
const skip = src == 'Web' || src == 'Mobile' || src == 'Internal Trading';

const entry = {{workflowparams:allData.so_status}} == 'Draft' ? {{node:code_node_hVnUCBf3.data.entry}} : {{node:code_node_rPqQy5CD.data.table}};
const lines = (entry && entry.table_so) || [];

const itemIDs = skip ? [] : [...new Set(lines.filter(l => l.item_name).map(l => l.item_name))];

return { itemIDs: itemIDs, needsPacking: !skip && itemIDs.length > 0 };

let updatedLineItem = [];
let entry = {{workflowparams:allData.so_status}} == 'Draft' ? {{node:code_node_hVnUCBf3.data.entry}} : {{node:workflow_node_yxaOreDk.data.needApproval}} == 'Yes' ? {{node:workflow_node_yxaOreDk.data.data}} : {{node:code_node_rPqQy5CD.data.table}};

// --- Packing + weight (mirrors SOchangeItem.buildPackingWeightData) ---
// Only populated for created_source outside Web / Mobile / Internal Trading;
// otherwise the gated search node never ran and this resolves to null.
const packingItemsRaw = {{node:search_node_PkItems.data.data}};
const packingItems = Array.isArray(packingItemsRaw) ? packingItemsRaw : (packingItemsRaw ? [packingItemsRaw] : []);
const needsPacking = packingItems.length > 0;

// --- Authoritative line counters ---
// planned_qty and delivered_qty are owned by the delivery and the picking plan, not by
// this page. table_so is written as one whole array, so spreading the browser's copy
// puts a stale tab's numbers back over whatever they wrote. Take them from the SO as
// stored, overlaid with whatever the cascade just left behind.
const prevSoRaw = {{node:get_node_rvjWbHBF.data.data}};
const prevSo = Array.isArray(prevSoRaw) ? prevSoRaw[0] || null : prevSoRaw || null;
const cascadeCounters = {{node:workflow_node_CascadeA.data.soLineCounters}};

const flattenSo = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const storedCounters = {};
flattenSo(prevSo && prevSo.table_so).forEach((r) => {
  if (r && r.id) storedCounters[String(r.id)] = r;
});
const cascadedCounters = {};
(Array.isArray(cascadeCounters) ? cascadeCounters : []).forEach((r) => {
  if (r && r.id) cascadedCounters[String(r.id)] = r;
});

// Both maps are empty on Add / Clone / Draft, where a row carries no id and nothing has
// been planned or delivered yet.
const lineCounters = (soLineItem) => {
  const key = soLineItem.id ? String(soLineItem.id) : "";
  const cascaded = key ? cascadedCounters[key] : null;
  const stored = key ? storedCounters[key] : null;
  const pick = (field) =>
    cascaded ? Number(cascaded[field]) || 0 : stored ? Number(stored[field]) || 0 : 0;
  return { delivered: pick("delivered_qty"), planned: pick("planned_qty") };
};

const round3 = (n) => Math.round((Number(n) || 0) * 1000) / 1000;
const getPackingDetail = (tpd, uom) => (!Array.isArray(tpd) || !tpd.length || !uom) ? null : (tpd.find((c) => c.uom_id === uom) || null);
const getBaseQty = (tuc, uom) => {
  if (!Array.isArray(tuc) || !tuc.length || !uom) return 1;
  const c = tuc.find((x) => x.alt_uom_id === uom);
  return c && c.base_qty ? c.base_qty : 1;
};
const buildPackingWeightData = (item, uom, soQuantity) => {
  const pd = getPackingDetail(item.table_packing_detail, uom);
  const packingConversion = (pd && pd.quantity) || 1;
  const weightConversion = round3((Number(item.net_weight) || 0) * getBaseQty(item.table_uom_conversion, uom));
  const qty = Number(soQuantity) || 0;
  return {
    packing_uom: (pd && pd.packing_uom_id) || '',
    packing_conversion: parseFloat(packingConversion || 0).toFixed(3),
    packing_qty: (packingConversion ? round3(qty / packingConversion) : 0).toFixed(3),
    weight_conversion: weightConversion.toFixed(3),
    net_weight: round3(qty * weightConversion).toFixed(3)
  };
};

// Header fields shared by every line, parent and child alike
const commonFields = {
  plant_id: entry.plant_name || "",
  customer_id: entry.customer_name || "",
  payment_term_id: entry.so_payment_term || "",
  sales_person_id: entry.so_sales_person || "",
  billing_state_id: entry.billing_address_state || "",
  billing_country_id: entry.billing_address_country || "",
  shipping_state_id: entry.shipping_address_state || "",
  shipping_country_id: entry.shipping_address_country || "",
  area_id: entry.so_area_id || "",
  organization_id: entry.organization_id,
  access_group: entry.access_group || [],
  agent_user_id: entry.so_agent_user_id || '',
};

const formatLine = (soLineItem) => {
  const counters = lineCounters(soLineItem);
  const formattedItem = {
    // Copy all existing properties
    ...soLineItem,

    // Apply number formatting to numeric fields
    unrestricted_qty: parseFloat(soLineItem.unrestricted_qty || 0).toFixed(3),
    base_unrestricted_qty: parseFloat(soLineItem.base_unrestricted_qty || 0).toFixed(3),
    so_quantity: parseFloat(soLineItem.so_quantity || 0).toFixed(3),
    so_item_price: parseFloat(soLineItem.so_item_price || 0).toFixed(4),
    so_gross: parseFloat(soLineItem.so_gross || 0).toFixed(4),
    so_discount: parseFloat(soLineItem.so_discount || 0).toFixed(4),
    so_discount_amount: parseFloat(soLineItem.so_discount_amount || 0).toFixed(4),
    so_tax_amount: parseFloat(soLineItem.so_tax_amount || 0).toFixed(4),
    min_price: parseFloat(soLineItem.min_price || 0).toFixed(4),
    max_price: parseFloat(soLineItem.max_price || 0).toFixed(4),
    so_amount: parseFloat(soLineItem.so_amount || 0).toFixed(4),
    production_planned_qty: parseFloat(soLineItem.so_quantity || 0).toFixed(3),
    production_status: "Not Created",
    // toFixed strings: both columns are decimal(_, 3) and a raw float trips multipleOf.
    delivered_qty: counters.delivered.toFixed(3),
    planned_qty: counters.planned.toFixed(3),
    // Clamped: over-delivery tolerance drives this negative, which the column rejects.
    outstanding_quantity: Math.max(0, parseFloat(soLineItem.so_quantity || 0) - counters.delivered).toFixed(3),

    so_shipping_date: soLineItem.so_shipping_date ?? entry.so_shipping_date,
  };

  if (needsPacking && soLineItem.item_name) {
    const itemData = packingItems.find((d) => String(d.id) === String(soLineItem.item_name));
    if (itemData) {
      Object.assign(formattedItem, buildPackingWeightData(itemData, soLineItem.so_item_uom, soLineItem.so_quantity));
    }
  }

  return formattedItem;
};

for (const [index, soLineItem] of entry.table_so.entries()) {
  const lineStatus =
    !soLineItem.line_status ||
    soLineItem.line_status === '' ||
    soLineItem.line_status === 'Draft'
      ? entry.so_status === 'Processing' ? 'Issued' : entry.so_status
      : soLineItem.line_status;

  const formattedItem = {
    ...formatLine(soLineItem),
    ...commonFields,
    line_index: index + 1,
    line_status: lineStatus,

    // If got child, give it the same formatting and header fields
    ...(Array.isArray(soLineItem.children) && {
      children: soLineItem.children.map((child, childIndex) => ({
        ...formatLine(child),
        ...commonFields,
        line_index: `${index + 1}/${childIndex + 1}`,
        line_status: lineStatus,
      })),
    }),
  };

  updatedLineItem.push(formattedItem);
}

entry.need_cl = ''

entry.production_status = !entry.production_status || entry.production_status === '' ? 'Not Created' : entry.production_status;

entry.si_status = !entry.si_status || entry.si_status === '' ? 'Not Created' : entry.si_status;
entry.so_total_gross = parseFloat(entry.so_total_gross || 0).toFixed(4);
entry.so_total_discount = parseFloat(entry.so_total_discount || 0).toFixed(4);
entry.so_total_tax = parseFloat(entry.so_total_tax || 0).toFixed(4);
entry.so_total = parseFloat(entry.so_total || 0).toFixed(4);
entry.myr_total_amount = parseFloat(entry.myr_total_amount || 0).toFixed(4);


entry.table_so = updatedLineItem;

return { entry };

const lineItem = {{node:code_node_BtxYhPym.data.entry.table_so}};

const uniqueItemIDs = [
  ...new Set(lineItem.filter((item) => item.item_name).map((item) => item.item_name))
];

return {
  itemIDs: uniqueItemIDs
}

// Pass B. A line added during this save had no row id while pass A ran, and GD's
// code_node_QtyCheckBatch throws outright on a so_line_item_id it cannot resolve -- so
// the append waits until the sales order row is written and code_node_9wKKlXUI has
// re-read it with the platform-assigned ids in place.
const soDataRaw = {{node:code_node_9wKKlXUI.data.soData}};
const prevSoRaw = {{node:get_node_rvjWbHBF.data.data}};
const allData = {{workflowparams:allData}};

const soData = Array.isArray(soDataRaw) ? soDataRaw[0] || null : soDataRaw || null;
const prevSo = Array.isArray(prevSoRaw) ? prevSoRaw[0] || null : prevSoRaw || null;

const flat = (rows) =>
  (Array.isArray(rows) ? rows : []).flatMap((r) =>
    [r].concat(Array.isArray(r && r.children) ? r.children : [])
  );
const sid = (v) => String(v === null || v === undefined ? "" : v);

// No stored SO means this was an Add, and a brand new order has no delivery to join.
if (!soData || !prevSo) {
  return { needsAppend: 0, soId: "", prevTableSo: [], nextTableSo: [] };
}

const prevIds = {};
flat(prevSo.table_so).forEach((r) => { if (r && r.id) prevIds[sid(r.id)] = 1; });
const added = flat(soData.table_so).filter(
  (r) => r && r.id && !prevIds[sid(r.id)] && r.item_name
);

return {
  needsAppend: added.length ? 1 : 0,
  soId: sid(soData.id || allData.id),
  prevTableSo: prevSo.table_so || [],
  nextTableSo: soData.table_so || []
};

// The gates return HTTP 200 with the code in the BODY, the way GDheadWorkflow's
// return-nodes do. A non-2xx end-node makes runWorkflow REJECT, and the platform then
// raises its own error toast beside the confirm -- rendering the raw <br> tags, because
// that toast takes no dangerouslyUseHTMLString. gateCode is what tells the client this
// is a gate rather than a saved order.
return {
  gate: {
    gateCode: {{node:workflow_node_CascadeB.data.code}} || "",
    message: {{node:workflow_node_CascadeB.data.message}} || ""
  }
};

let latestSOData = {{node:code_node_9wKKlXUI.data.soData}};
if(latestSOData.so_no_type !== -9999 && (latestSOData.previous_status === 'Draft' || latestSOData.previous_status == '')) {
  latestSOData.so_no = 'issued';
}
latestSOData.so_status = 'Issued';

return {
  latestSOData
}

const soData = {{node:code_node_9wKKlXUI.data.soData}}
return {
  sqt_id: soData?.sqt_id || []
}

let soData = {{node:get_node_NCJ7taxf.data.data}};

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// An item bundle is ONE line on the order with the bundle's items beneath it.
// The receivable keeps that shape: the bundle is one line with its items under
// `children`.
//
// The bundle line carries the money. Its gross, discount, tax and amount on the
// order are already the sum of its items -- that is what so_total is built from
// -- so mapping the items as receivable lines of their own bills the bundle
// twice. They come across for what they show and are never added again.
// Nothing re-sums these lines: tax_total, invoice_total and outstanding_amount
// all come straight off the order.
//
// Note table_so's field names are inverted: item_name holds the item's id and
// item_id holds its name, so item_name is what tells a bundle line (no item of
// its own) from an item under it.
// ==========================================================================

const mapLineItem = (item, record, index) => {
  const lineItemPromise = {
    item_id: item.item_name,
    item_name: item.item_id,
    item_description: item.so_desc,
    item_bundle_id: bundleKey(item),
    amount: (
      parseFloat(item.so_gross) - parseFloat(item.so_discount_amount || 0)
    ).toFixed(4),
    tax_code: item.so_tax_preference,
    tax_percent: item.so_tax_percentage,
    tax_inclusive: item.so_tax_inclusive,
    tax_tariff_id: item.tariff_id,
    tax_amount: parseFloat(item.so_tax_amount).toFixed(4),
    subtotal: parseFloat(item.so_amount).toFixed(4),
    customer_id: item.customer_id,
    area_id: item.area_id,
    agent_id: item.sales_person_id,
    payment_term_id: item.payment_term_id,
    plant_id: item.organization_id,
    organization_id: item.organization_id,
    project_id: item.project_id ?? null,
  };

  return lineItemPromise;
};

const mapHeaderData = (record, lineItemPromise) => {
  const data = {
    payment_status: "Unpaid",
    plant_id: record.organization_id,
    organization_id: record.organization_id,
    ar_invoice_no: record.so_no,
    ar_invoice_no_type: -9999,
    customer_id: record.customer_name,
    currency_code: record.so_currency,
    description: "Sales",
    ar_billing_address: record.cust_billing_address,
    ar_shipping_address: record.cust_shipping_address,
    invoice_date: new Date().toISOString().split("T")[0],
    area_id: record.so_area_id || "",
    agent_id: record.so_sales_person,
    agent_user_id: record.so_agent_user_id,
    payment_term_id: record.so_payment_term,
    due_date: new Date().toISOString().split("T")[0],
    so_id: record.id,
    project_id: record.project_id ?? null,
    table_ar_invoice: lineItemPromise,
    tax_total_currency: record.so_currency,
    invoice_total_currency: record.so_currency,
    outstanding_amount_currency: record.so_currency,
    tax_total: parseFloat(record.so_total_tax).toFixed(4),
    invoice_total: parseFloat(record.so_total).toFixed(4),
    outstanding_amount: parseFloat(record.so_total).toFixed(4),
    myr_invoice_total: parseFloat(record.myr_total_amount).toFixed(4),
    billing_address_name: record.billing_address_name,
    billing_address_phone: record.billing_address_phone,
    billing_address_line_1: record.billing_address_line_1,
    billing_address_line_2: record.billing_address_line_2,
    billing_address_line_3: record.billing_address_line_3,
